// Artifact-declared types (slc/link.md §PlaybookRuntime contract:
// host-supplied port-shaped callbacks are linker-exposed option members whose
// types the artifact itself declares, so `PlaybookPorts` stays six members).
export type { EnabledPlaybook };

/** One nonempty complete standalone request selected for `start` or `switch`. */
export type CaptainControllerInput = string;

/** One validated controller selection submitted through the port (DR-029, DR-038). */
export type CaptainControllerSelection =
  | { readonly action: 'respond'; readonly text: string }
  | { readonly action: 'resume'; readonly playbookId: string }
  | {
      readonly action: 'start' | 'switch';
      readonly playbookId: string;
      /** Complete standalone request synthesized from the remembered Boss conversation. */
      readonly input: CaptainControllerInput;
      readonly attachmentIds?: readonly string[];
    }
  | { readonly action: 'dismiss' | 'recover' }
  | { readonly action: 'deliver'; readonly attachmentIds?: readonly string[] }
  | { readonly action: 'runtime'; readonly actionId: string };

/**
 * The host's deterministic per-turn resolution: `undefined` sends the turn to
 * the hidden decision call (BOSS_TURN_UNRESOLVED → decide); `respond` routes
 * the dedicated command answer (BOSS_TURN_RESPOND → command); `action` is a
 * parse-resolved acting turn the host has already validated and executed, so
 * the runtime only composes its closing reply (BOSS_TURN_ACTING → close); and
 * `shutdown` is the host teardown entry to the machine's one final state
 * (HOST_TEARDOWN → shutdown).
 */
export type CaptainParsedResolution =
  | { readonly kind: 'respond' }
  | { readonly kind: 'action' }
  | { readonly kind: 'shutdown' };

/** Compact `{ name, message }` error evidence (never a raw Error). */
export interface CompactError {
  readonly name: string;
  readonly message: string;
}

/** Receipt evidence of an executed action (disposition only). */
export interface SettlementReceiptEvidence {
  readonly disposition: 'executed' | 'rejected' | 'failed';
  readonly reason?: string;
  readonly error?: CompactError;
}

/** Bounded host-owned evidence for one unresolved repository effect. */
export interface SettlementUnresolvedEffectEvidence {
  readonly classification:
    | 'one-descendant-commit'
    | 'multiple-commits'
    | 'rewritten-or-non-descendant'
    | 'worktree-only-change'
    | 'concurrent-or-foreign-change'
    | 'observation-ambiguous'
    | 'incomplete';
  readonly baselineHead: string;
  readonly afterHead?: string;
  readonly commitOid?: string;
}

/**
 * The controller-port settlement evidence the host returns for a submitted
 * selection: status, outcome-report facts, the exact bounded unresolved
 * effects, an optional rejection reason, an optional structured receipt, and a
 * leaf-state summary — never a session id, call id, child state, stack ledger,
 * resume token, or opaque runtime result (source "As decision and reply
 * evidence …"). The runtime treats it as the only evidence of what happened;
 * this machine does not thread it, so the host surfaces its outcome report to
 * the close call through the durable conversation it owns.
 */
export interface SettlementEvidence {
  readonly status: 'ok' | 'rejected' | 'failed';
  readonly facts: readonly string[];
  readonly unresolvedEffects: readonly SettlementUnresolvedEffectEvidence[];
  readonly reason?: string;
  readonly receipt?: SettlementReceiptEvidence;
  readonly leafStateSummary?: string;
}

/**
 * The host-supplied controller port (DR-029): one validated selection per
 * model-decided Boss turn in, its settlement back as the only evidence of
 * effects. The optional `resolveParsedTurn` member supplies the host's
 * deterministic command-parse resolution for the entry mapping.
 */
export interface CaptainControllerPort {
  submit(
    selection: CaptainControllerSelection,
    signal: AbortSignal,
  ): Promise<SettlementEvidence>;
  resolveParsedTurn?(text: string): CaptainParsedResolution | undefined;
}

export interface PlaybookRuntimeOptions {
  readonly enabledPlaybooks: readonly EnabledPlaybook[];
  /**
   * The host-supplied controller port. Every model-decided Boss turn settles
   * its selection through it, so it is declared required.
   */
  readonly controller: CaptainControllerPort;
}

/**
 * The validated option record the engine carries. It differs from the public
 * declaration in exactly one place: `controller` is optional here, because a
 * construction from untyped JavaScript can still omit it and the shape has to
 * describe what validation actually accepts. Where that ends is
 * `requireControllerPort` — the first submitted selection, with a named error
 * rather than a silent one.
 */
type ValidatedCaptainOptions = Omit<PlaybookRuntimeOptions, 'controller'> & {
  readonly controller?: CaptainControllerPort;
};

function assertNonEmptyString(value: unknown, label: string): string {
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new TypeError(`${label} must be a non-empty string`);
  }
  return value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

const ATTACHMENT_ID_PATTERN = /^sha256:[0-9a-f]{64}$/;

function isValidAttachmentIds(value: unknown): value is readonly string[] {
  return (
    Array.isArray(value) &&
    value.every(
      (id) => typeof id === 'string' && ATTACHMENT_ID_PATTERN.test(id),
    ) &&
    new Set(value as readonly string[]).size === value.length
  );
}

function validateEnabledPlaybooks(value: unknown): readonly EnabledPlaybook[] {
  if (!Array.isArray(value)) {
    throw new TypeError('enabledPlaybooks must be an array');
  }
  const ids = new Set<string>();
  return Object.freeze(
    value.map((entry: unknown, index) => {
      if (!isRecord(entry)) {
        throw new TypeError(`enabledPlaybooks[${index}] must be an object`);
      }
      const keys = Object.keys(entry).sort();
      if (keys.join('\0') !== ['command', 'id', 'intent'].join('\0')) {
        throw new TypeError(
          `enabledPlaybooks[${index}] must contain exactly id, command, and intent`,
        );
      }
      const id = assertNonEmptyString(entry.id, `enabledPlaybooks[${index}].id`);
      const command = assertNonEmptyString(
        entry.command,
        `enabledPlaybooks[${index}].command`,
      );
      const intent = assertNonEmptyString(
        entry.intent,
        `enabledPlaybooks[${index}].intent`,
      );
      if (ids.has(id)) {
        throw new TypeError(`enabledPlaybooks id ${id} is duplicated`);
      }
      ids.add(id);
      return Object.freeze({ id, command, intent });
    }),
  );
}

function validateControllerPort(value: unknown): CaptainControllerPort {
  if (value === null || typeof value !== 'object') {
    throw new TypeError('options.controller must be an object');
  }
  const record = value as Record<string, unknown>;
  if (typeof record.submit !== 'function') {
    throw new TypeError('options.controller.submit must be a function');
  }
  if (
    record.resolveParsedTurn !== undefined &&
    typeof record.resolveParsedTurn !== 'function'
  ) {
    throw new TypeError(
      'options.controller.resolveParsedTurn must be a function when present',
    );
  }
  return value as CaptainControllerPort;
}

function snapshotCaptainOptions(value: unknown): ValidatedCaptainOptions {
  if (!isRecord(value)) {
    throw new TypeError('Captain runtime options must be an object');
  }
  const allowed = new Set(['enabledPlaybooks', 'controller']);
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) {
      throw new TypeError(`Captain runtime options.${key} is not declared`);
    }
  }
  const enabledPlaybooks = validateEnabledPlaybooks(value.enabledPlaybooks);
  const controller =
    value.controller === undefined
      ? undefined
      : validateControllerPort(value.controller);
  return Object.freeze({
    enabledPlaybooks,
    ...(controller === undefined ? {} : { controller }),
  });
}

// ---------------------------------------------------------------------------
// Deterministic controller entry mapping (slc/link.md §Boss-event mapping):
// the host's parse resolution selects the hub entry event; no classifier judge
// call runs. The FSM's entry events carry no payload — the hidden controller
// form keeps the exact Boss text on the host's durable conversation, not in
// machine context.
// ---------------------------------------------------------------------------

function classifyControllerTurn(
  text: string,
  _ports: PlaybookPorts,
  _signal: AbortSignal,
  _snapshotOrState: unknown,
  _boundary?: unknown,
  options?: ValidatedCaptainOptions,
): Promise<Record<string, unknown> | undefined> {
  const resolution = options?.controller?.resolveParsedTurn?.(text);
  if (resolution === undefined) {
    return Promise.resolve({ type: 'BOSS_TURN_UNRESOLVED' });
  }
  if (!isRecord(resolution)) {
    throw new TypeError('controller parse resolution must be an object');
  }
  const widened = resolution as { readonly kind?: unknown };
  switch (widened.kind) {
    case 'respond':
      return Promise.resolve({ type: 'BOSS_TURN_RESPOND' });
    case 'action':
      // A parse-resolved acting turn is validated and executed host-side; the
      // runtime only composes its closing reply (BOSS_TURN_ACTING → close).
      return Promise.resolve({ type: 'BOSS_TURN_ACTING' });
    case 'shutdown':
      return Promise.resolve({ type: 'HOST_TEARDOWN' });
    default:
      throw new TypeError(
        `controller parse resolution names unknown kind ${String(widened.kind)}`,
      );
  }
}

// ---------------------------------------------------------------------------
// Decision-reply validation (CAPPLAY-18): the hidden decide call's reply is
// `{ action, … }` control JSON over the closed set, validated against the
// declared decision-state contract — known action, required payload fields,
// catalog membership, never this Captain playbook itself as a target. A
// malformed reply earns exactly one corrective call appending the rejection
// reason and the restated reply contract; a second malformed reply routes the
// FSM's recoverable failure path with no action executed.
// ---------------------------------------------------------------------------

const RESTATED_REPLY_CONTRACT = [
  'Reply again with exactly one JSON object `{ "action": …, … }` and no other text, selecting exactly one action from the closed set `respond` | `resume` | `start` | `switch` | `dismiss` | `deliver` | `runtime` | `recover`:',
  '`{ "action": "respond", "text": … }`, `{ "action": "resume", "playbookId": … }`, `{ "action": "start", "playbookId": …, "input": … }`, `{ "action": "switch", "playbookId": …, "input": … }`, `{ "action": "dismiss" }`, `{ "action": "deliver" }`, `{ "action": "runtime", "actionId": … }`, or `{ "action": "recover" }`; every `input` is one nonempty complete standalone request.',
].join('\n');

function correctiveDecisionPrompt(prompt: string, reason: string): string {
  return [
    prompt,
    '',
    `Your previous control reply was rejected: ${reason}.`,
    RESTATED_REPLY_CONTRACT,
  ].join('\n');
}

type DecisionReplyReading =
  | { readonly selection: CaptainControllerSelection; readonly reason?: undefined }
  | { readonly selection?: undefined; readonly reason: string };

function readDecisionReply(
  reply: string,
  options: ValidatedCaptainOptions,
  selfPlaybookId: string,
  declaredActions: ReadonlySet<string>,
): DecisionReplyReading {
  let parsed: unknown;
  try {
    parsed = parseJudgeJson(reply);
  } catch {
    return { reason: 'the reply contains no recoverable JSON object' };
  }
  if (!isRecord(parsed)) {
    return { reason: 'the reply is not a JSON object' };
  }
  const action = parsed.action;
  if (typeof action !== 'string' || !declaredActions.has(action)) {
    return {
      reason: `the reply names no known action (got ${JSON.stringify(action ?? null)})`,
    };
  }
  const requireKeys = (
    required: readonly string[],
    tolerated: readonly string[] = [],
  ): string | undefined => {
    for (const key of required) {
      if (!(key in parsed)) {
        return `the ${action} selection omits required field \`${key}\``;
      }
    }
    for (const key of Object.keys(parsed)) {
      if (
        key !== 'action' &&
        !required.includes(key) &&
        !tolerated.includes(key)
      ) {
        return `the ${action} selection carries undeclared field \`${key}\``;
      }
    }
    return undefined;
  };
  const nonEmpty = (key: string): string | undefined =>
    typeof parsed[key] === 'string' && (parsed[key] as string).trim().length > 0
      ? undefined
      : `the ${action} selection's \`${key}\` must be a non-empty string`;
  const attachments = parsed.attachmentIds;
  const attachmentIssue =
    attachments !== undefined && !isValidAttachmentIds(attachments)
      ? 'attachmentIds must be unique supplied asset identifiers'
      : undefined;
  switch (action) {
    case 'respond': {
      const shape = requireKeys(['text']) ?? nonEmpty('text');
      if (shape !== undefined) return { reason: shape };
      return { selection: { action, text: parsed.text as string } };
    }
    case 'resume': {
      const shape = requireKeys(['playbookId']) ?? nonEmpty('playbookId');
      if (shape !== undefined) return { reason: shape };
      const playbookId = parsed.playbookId as string;
      if (playbookId === selfPlaybookId) {
        return {
          reason: `the ${action} target may never be this Captain playbook itself`,
        };
      }
      if (!options.enabledPlaybooks.some((entry) => entry.id === playbookId)) {
        return {
          reason: `the ${action} target ${JSON.stringify(playbookId)} is not an enabled catalog id`,
        };
      }
      return { selection: { action, playbookId } };
    }
    case 'start':
    case 'switch': {
      const shape =
        requireKeys(['playbookId', 'input'], ['attachmentIds']) ??
        nonEmpty('playbookId') ??
        nonEmpty('input') ??
        attachmentIssue;
      if (shape !== undefined) return { reason: shape };
      const playbookId = parsed.playbookId as string;
      if (playbookId === selfPlaybookId) {
        return {
          reason: `the ${action} target may never be this Captain playbook itself`,
        };
      }
      if (!options.enabledPlaybooks.some((entry) => entry.id === playbookId)) {
        return {
          reason: `the ${action} target ${JSON.stringify(playbookId)} is not an enabled catalog id`,
        };
      }
      return {
        selection: {
          action,
          playbookId,
          input: parsed.input as string,
          ...(attachments === undefined
            ? {}
            : { attachmentIds: attachments as readonly string[] }),
        },
      };
    }
    case 'recover':
    case 'dismiss': {
      const shape = requireKeys([]);
      if (shape !== undefined) return { reason: shape };
      return { selection: { action } };
    }
    case 'deliver': {
      // A deliver selection carries no text payload: the host is authoritative
      // for the delivered text, so a carried `text` is ignored and never
      // delivered. An optional `attachmentIds` list may still accompany it.
      const shape = requireKeys([], ['text', 'attachmentIds']) ?? attachmentIssue;
      if (shape !== undefined) return { reason: shape };
      return {
        selection: {
          action,
          ...(attachments === undefined
            ? {}
            : { attachmentIds: attachments as readonly string[] }),
        },
      };
    }
    case 'runtime': {
      const shape = requireKeys(['actionId']) ?? nonEmpty('actionId');
      if (shape !== undefined) return { reason: shape };
      return { selection: { action, actionId: parsed.actionId as string } };
    }
    default:
      return { reason: `the reply names no known action (${action})` };
  }
}

/**
 * The actor output the FSM's `decide` state routes on: exactly the selected
 * guard plus its declared payload fields (CaptainOutput). This machine retains
 * no settlement, so no settlement member is attached.
 */
function decisionOutputOf(
  selection: CaptainControllerSelection,
): PlaybookActorOutput {
  switch (selection.action) {
    case 'respond':
      return { guard: 'respond', text: selection.text };
    case 'resume':
      return { guard: 'resume', playbookId: selection.playbookId };
    case 'start':
    case 'switch':
      return {
        guard: selection.action,
        playbookId: selection.playbookId,
        input: selection.input,
        ...(selection.attachmentIds === undefined
          ? {}
          : { attachmentIds: selection.attachmentIds }),
      };
    case 'deliver':
      return {
        guard: 'deliver',
        ...(selection.attachmentIds === undefined
          ? {}
          : { attachmentIds: selection.attachmentIds }),
      };
    case 'runtime':
      return { guard: 'runtime', actionId: selection.actionId };
    case 'dismiss':
      return { guard: 'dismiss' };
    case 'recover':
      return { guard: 'recover' };
  }
}

// ---------------------------------------------------------------------------
// Settlement validation: the returned settlement is the only evidence of
// effects, and a malformed settlement is a host control-plane failure. This
// machine retains only the fact that the submission settled; the host carries
// the outcome report to the close call through its durable conversation.
// ---------------------------------------------------------------------------

const SETTLEMENT_GIT_OID_PATTERN = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/;
const SETTLEMENT_UNRESOLVED_CLASSIFICATIONS = new Set<
  SettlementUnresolvedEffectEvidence['classification']
>([
  'one-descendant-commit',
  'multiple-commits',
  'rewritten-or-non-descendant',
  'worktree-only-change',
  'concurrent-or-foreign-change',
  'observation-ambiguous',
  'incomplete',
]);

function validateSettlementUnresolvedEffects(
  value: unknown,
): readonly SettlementUnresolvedEffectEvidence[] {
  const detached = snapshotJsonValue(
    value,
    'controller settlement unresolvedEffects',
  );
  if (!Array.isArray(detached)) {
    throw new TypeError(
      'controller settlement unresolvedEffects must be an array',
    );
  }
  for (const [index, raw] of detached.entries()) {
    const path = `controller settlement unresolvedEffects[${index}]`;
    if (!isRecord(raw)) {
      throw new TypeError(`${path} must be an object`);
    }
    const allowed = new Set([
      'classification',
      'baselineHead',
      'afterHead',
      'commitOid',
    ]);
    const unknown = Object.keys(raw).find((key) => !allowed.has(key));
    if (unknown !== undefined) {
      throw new TypeError(`${path} carries undeclared ${unknown}`);
    }
    if (
      typeof raw.classification !== 'string' ||
      !SETTLEMENT_UNRESOLVED_CLASSIFICATIONS.has(
        raw.classification as SettlementUnresolvedEffectEvidence['classification'],
      )
    ) {
      throw new TypeError(`${path} classification is not supported`);
    }
    if (
      typeof raw.baselineHead !== 'string' ||
      !SETTLEMENT_GIT_OID_PATTERN.test(raw.baselineHead)
    ) {
      throw new TypeError(`${path} baselineHead must be a Git OID`);
    }
    if (
      'afterHead' in raw &&
      (typeof raw.afterHead !== 'string' ||
        !SETTLEMENT_GIT_OID_PATTERN.test(raw.afterHead))
    ) {
      throw new TypeError(`${path} afterHead must be a Git OID`);
    }
    if (
      raw.classification !== 'observation-ambiguous' &&
      raw.classification !== 'incomplete' &&
      !('afterHead' in raw)
    ) {
      throw new TypeError(
        `${path} afterHead is required for ${raw.classification}`,
      );
    }
    if (raw.classification === 'one-descendant-commit') {
      if (
        typeof raw.commitOid !== 'string' ||
        !SETTLEMENT_GIT_OID_PATTERN.test(raw.commitOid) ||
        raw.commitOid !== raw.afterHead
      ) {
        throw new TypeError(
          `${path} commitOid must equal afterHead for one-descendant-commit`,
        );
      }
    } else if ('commitOid' in raw) {
      throw new TypeError(
        `${path} commitOid is permitted only for one-descendant-commit`,
      );
    }
  }
  return detached as unknown as readonly SettlementUnresolvedEffectEvidence[];
}

function validateSettlement(value: unknown): SettlementEvidence {
  if (!isRecord(value)) {
    throw new TypeError('controller settlement must be an object');
  }
  const allowed = new Set([
    'status',
    'facts',
    'unresolvedEffects',
    'reason',
    'receipt',
    'leafStateSummary',
  ]);
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) {
      throw new TypeError(`controller settlement carries undeclared ${key}`);
    }
  }
  if (
    value.status !== 'ok' &&
    value.status !== 'rejected' &&
    value.status !== 'failed'
  ) {
    throw new TypeError(
      `controller settlement status must be ok | rejected | failed (got ${String(value.status)})`,
    );
  }
  if (
    !Array.isArray(value.facts) ||
    value.facts.some((fact: unknown) => typeof fact !== 'string')
  ) {
    throw new TypeError('controller settlement facts must be a string array');
  }
  if (!Object.prototype.hasOwnProperty.call(value, 'unresolvedEffects')) {
    throw new TypeError('controller settlement unresolvedEffects is required');
  }
  const unresolvedEffects = validateSettlementUnresolvedEffects(
    value.unresolvedEffects,
  );
  if ('reason' in value && typeof value.reason !== 'string') {
    throw new TypeError('controller settlement reason must be a string');
  }
  if (
    'leafStateSummary' in value &&
    typeof value.leafStateSummary !== 'string'
  ) {
    throw new TypeError(
      'controller settlement leafStateSummary must be a string',
    );
  }
  let receipt: SettlementReceiptEvidence | undefined;
  if ('receipt' in value) {
    if (!isRecord(value.receipt)) {
      throw new TypeError('controller settlement receipt must be an object');
    }
    const receiptAllowed = new Set(['disposition', 'reason', 'error']);
    for (const key of Object.keys(value.receipt)) {
      if (!receiptAllowed.has(key)) {
        throw new TypeError(
          `controller settlement receipt carries undeclared ${key}`,
        );
      }
    }
    const disposition = value.receipt.disposition;
    if (
      disposition !== 'executed' &&
      disposition !== 'rejected' &&
      disposition !== 'failed'
    ) {
      throw new TypeError(
        'controller settlement receipt disposition must be executed | rejected | failed',
      );
    }
    if ('reason' in value.receipt && typeof value.receipt.reason !== 'string') {
      throw new TypeError(
        'controller settlement receipt reason must be a string',
      );
    }
    let error: CompactError | undefined;
    if ('error' in value.receipt) {
      const compact = normalizeErrorCompact(value.receipt.error);
      if (compact === undefined) {
        throw new TypeError(
          'controller settlement receipt error must be a normalized error',
        );
      }
      error = compact;
    }
    receipt = Object.freeze({
      disposition,
      ...(typeof value.receipt.reason === 'string'
        ? { reason: value.receipt.reason }
        : {}),
      ...(error === undefined ? {} : { error: Object.freeze(error) }),
    });
  }
  return Object.freeze({
    status: value.status,
    facts: Object.freeze([...(value.facts as readonly string[])]),
    unresolvedEffects,
    ...(typeof value.reason === 'string' ? { reason: value.reason } : {}),
    ...(receipt === undefined ? {} : { receipt }),
    ...(typeof value.leafStateSummary === 'string'
      ? { leafStateSummary: value.leafStateSummary }
      : {}),
  });
}

// ---------------------------------------------------------------------------
// The controller captain-call strategy (slc/link.md §Captain adjudication,
// controller form). The engine composes the prompt, traces every call as its
// own captain.call pair on the shared serialized lane, and owns control-plane
// latching; this strategy owns the hidden calls, the decision validation with
// its one corrective re-ask, and the controller-port submission.
// ---------------------------------------------------------------------------

const HIDDEN = { visibility: 'hidden' } as const;

async function callHidden(
  run: XStateCaptainStrategyRun<ValidatedCaptainOptions>,
  prompt: string,
): Promise<CaptainResult> {
  try {
    return await run.callCaptain(prompt, HIDDEN);
  } catch (error) {
    // DR-028: exactly one corrective re-ask of the same composed call on an
    // empty `ok` result; a second such result follows the failure path from
    // the boundary itself.
    if (!run.isEmptyOkRetry(error)) throw error;
    return await run.callCaptain(prompt, HIDDEN);
  }
}

function requireControllerPort(
  options: ValidatedCaptainOptions,
): CaptainControllerPort {
  if (options.controller === undefined) {
    throw new Error(
      'captain.playbook: the host-supplied controller port is required to settle a Boss turn; construct the runtime with options.controller',
    );
  }
  return options.controller;
}

async function submitSelection(
  run: XStateCaptainStrategyRun<ValidatedCaptainOptions>,
  selection: CaptainControllerSelection,
): Promise<void> {
  const port = requireControllerPort(run.options);
  // The returned settlement is validated as the host's evidence of what
  // happened; this machine retains none of it, so it is discarded after the
  // control-plane shape check.
  validateSettlement(await port.submit(selection, run.signal));
  run.signal.throwIfAborted();
}

async function runDecisionState(
  run: XStateCaptainStrategyRun<ValidatedCaptainOptions>,
): Promise<PlaybookActorOutput> {
  const declaredActions = new Set(Object.keys(run.input.result));
  const first = await callHidden(run, run.prompt);
  const firstReading = readDecisionReply(
    first.finalText ?? '',
    run.options,
    run.session.playbookId,
    declaredActions,
  );
  let selection: CaptainControllerSelection;
  if (firstReading.selection !== undefined) {
    selection = firstReading.selection;
  } else {
    // CAPPLAY-18: exactly one corrective call appending the rejection reason
    // and the restated reply contract to the same prompt.
    const second = await callHidden(
      run,
      correctiveDecisionPrompt(run.prompt, firstReading.reason),
    );
    const secondReading = readDecisionReply(
      second.finalText ?? '',
      run.options,
      run.session.playbookId,
      declaredActions,
    );
    if (secondReading.selection === undefined) {
      // A second malformed reply settles the turn with no action executed and
      // the engagement untouched; the FSM's recoverable failure path parks the
      // machine for the next Boss turn (source "A second malformed reply …").
      const failure = new Error(
        `the decision reply stayed malformed after one corrective re-ask: ${secondReading.reason}`,
      );
      failure.name = 'ControllerDecisionError';
      throw run.recoverableFailure(failure);
    }
    selection = secondReading.selection;
  }
  // The validated selection is submitted once (source "the linked runtime
  // submits at most one validated selection through the host-supplied
  // controller port"). The machine then routes on the selected guard alone.
  await submitSelection(run, selection);
  return decisionOutputOf(selection);
}

async function controllerCaptainStrategy(
  run: XStateCaptainStrategyRun<ValidatedCaptainOptions>,
): Promise<PlaybookActorOutput> {
  if (run.input.stateId === 'decide') {
    return runDecisionState(run);
  }
  // The prose states (command, close): one hidden durable call whose validated
  // text the host surfaces as captain speech through its presentation seam; the
  // machine retains no reply prose and the state settles with the default
  // single-outcome `done` contract.
  await callHidden(run, run.prompt);
  return { guard: 'done' };
}

// ---------------------------------------------------------------------------
// Captain-pane status lines. The shell suppresses this runtime's human status
// stream while forwarding structured telemetry; the lines stay
// Boss-appropriate regardless. The parked hub (`ready`) and the terminal
// `shutdown` state emit no human status (slc/link.md §Session lifecycle).
// ---------------------------------------------------------------------------

function statusesForState(
  state: PlaybookState,
  context: Record<string, unknown>,
): ScheduledStatus[] {
  switch (state.stateId) {
    case 'decide':
      return [{ message: '⤷ Captain: decide the Boss turn' }];
    case 'command':
      return [{ message: '⤷ Captain: answer the command turn' }];
    case 'close':
      return [{ message: '⤷ Captain: compose the closing reply' }];
    case 'failed': {
      const lastError = normalizeErrorCompact(context.lastError);
      return [
        {
          message: '◆ failed',
          ...(lastError === undefined
            ? {}
            : { data: snapshotJsonValue({ lastError }, 'failed status data') }),
        },
      ];
    }
    default:
      return [];
  }
}

const UNFINISHED_FINAL_STATE_IDS: ReadonlySet<string> = new Set();

// Internal export surface for verification and tests. Not part of the stable
// public API; the leading underscore signals "subject to change."
export const _internal = {
  // No placeholder exists in any compiled Captain prompt: the labeled
  // Boss-message, ControlView digest, and catalog digest blocks are
  // shell-composed inside the hidden-control envelope, so the shared default
  // composer emits the verbatim GEARS domain body.
  composeCaptainPrompt: (input: CaptainInput): string =>
    defaultComposeCaptainPrompt(input as unknown as PlaybookCaptainInput),
  classifyControllerTurn,
  readDecisionReply,
  correctiveDecisionPrompt,
  decisionOutputOf,
  validateSettlement,
  statusesForState,
  normalizeError,
  UNFINISHED_FINAL_STATE_IDS,
};

// The Captain-specific spec handed to the shared runtime factory
// (slc/link.md §Output, DR-019). Generic machinery — actor wiring, boundary
// tracing, lifecycle, abort, the parked-session snapshot, and the DR-029
// describe/apply control surface — lives in @sublang/playbook/xstate-runtime.
const runtimeSpec: XStatePlaybookRuntimeSpecV3<ValidatedCaptainOptions> = {
  label: 'CAPTAIN',
  // DR-022 / slc/link.md: the declaration carries the value current at link
  // time — a literal, never the loading engine's RUNTIME_ABI self-report,
  // which would follow whatever engine loads the module and make the factory's
  // skew check compare that engine with itself.
  compat: { artifactSchema: 3, runtimeAbi: 1 },
  // DR-040: the roleless session Captain has no delegated-player outcome, but
  // schema 3 still makes that absence explicit rather than inferred.
  outcomeAuthority: { governedPlayerStates: {} },
  snapshotOptions: snapshotCaptainOptions,
  machineInput: (options) => ({ enabledPlaybooks: options.enabledPlaybooks }),
  classifyBossText: (text, ports, signal, snapshotOrState, boundary, options) =>
    classifyControllerTurn(
      text,
      ports,
      signal,
      snapshotOrState,
      boundary,
      options,
    ) as Promise<import('xstate').EventObject | undefined>,
  roleStates: {},
  classificationStatus: () => undefined,
  captainStrategy: controllerCaptainStrategy,
  // DR-029 / PBRT-52: the controller ControlView context projection. This
  // machine's only context members are the host-supplied catalog
  // (`enabledPlaybooks`, an option value) and `lastError` (surfaced
  // first-class by the view and forbidden here), so the view exposes no
  // context at all — an explicit empty projection, not an allow-by-default
  // serialization of FSM context.
  controlContextFields: [],
  unfinishedFinalStateIds: UNFINISHED_FINAL_STATE_IDS,
  statusesForState,
};

// DR-022's compat check fails fast at factory construction. The Captain is
// statically imported by the shell and both CLI front ends, so constructing
// here at module evaluation would turn a future compat mismatch into an
// uncaught ESM-load error that takes even `--help` down; constructing on the
// first runtime request keeps the failure inside the caught host-construction
// boundary that owes the Boss a setup diagnostic.
const rejectInternalCaptainRepositoryWork = async (): Promise<never> => {
  throw new Error(
    'the roleless session Captain cannot perform repository-governed work',
  );
};
const INTERNAL_CAPTAIN_HOST_CAPABILITIES = Object.freeze({
  // The engine does not consult this member for an explicitly empty governed
  // set. Keeping a fail-closed implementation satisfies the schema-3 factory
  // boundary without granting the internal controller repository authority.
  repository: Object.freeze({
    runExclusive: rejectInternalCaptainRepositoryWork,
    runDeferred: rejectInternalCaptainRepositoryWork,
  } satisfies XStateRepositoryCapability),
  effectLedger: Object.freeze({
    snapshot: emptyPlaybookEffectLedger,
    writeAhead: async (): Promise<never> => {
      throw new Error(
        'the roleless session Captain cannot write an effect ledger',
      );
    },
  }),
});

function buildCaptainPlaybookRuntimeFactory() {
  return createXStatePlaybookRuntime(captainMachine, runtimeSpec);
}

let createCaptainPlaybookRuntime:
  | ReturnType<typeof buildCaptainPlaybookRuntimeFactory>
  | undefined;

export function createPlaybookRuntime(
  options: PlaybookRuntimeOptions,
): PlaybookRuntime {
  createCaptainPlaybookRuntime ??= buildCaptainPlaybookRuntimeFactory();
  return createCaptainPlaybookRuntime({
    configuredOptions: options,
    hostCapabilities: INTERNAL_CAPTAIN_HOST_CAPABILITIES,
  });
}

const factory: PlaybookRuntimeFactory<PlaybookRuntimeOptions> =
  createPlaybookRuntime;

export default factory;
